INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (30000, "", 0, 24001, 2, 35, "", 0, 0, 1, 15);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40000, "", 0, 91002, 8, 36, "", 0, 0, 100, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "ぺコリーヌ", 1, 91002, 8, 37, "今日は記念日、お祝いですね！\n焼肉、お寿司、ピザ、ケーキ～☆\nあなたとパーティできるなんて、\n幸せです～♪", 107501, 0, 150, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "コッコロ", 1, 91002, 8, 38, "この記念日を迎えられたのは、\n主さまの器量の賜物\nさすがは主さまでございます\nえらい、えらい♪", 107601, 0, 150, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "キャル", 1, 91002, 8, 39, "あんたもけっこうやるじゃない！\nちょっとは…割と…け、けっこう\n見直しちゃったわ\n褒めてあげる♪", 107801, 0, 150, 3);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "スズメ", 1, 91002, 8, 40, "あなたと私にとって、\n今日は特別な日\nあなたの支えがあるから、\n私は頑張れるんです！", 107701, 0, 150, 4);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "タマキ", 1, 91002, 8, 41, "今日はキミにとっての\n特別な記念日だにゃ\nキミの活躍にはいつも\n猫ながら感謝してるにゃ～♪", 107901, 0, 150, 5);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "ぺコリーヌ", 2, 91002, 8, 42, "う～かき氷食べ過ぎて、\n身体が冷えちゃいました…\nあなたの体温で温めてください！\nギューーッ♪", 107501, 0, 150, 6);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "コッコロ", 2, 91002, 8, 43, "夏は危険がいっぱいと申します…\nですが、わたくしが主さまを\nしっかりとお守りいたしますよ", 107601, 0, 150, 7);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "キャル", 2, 91002, 8, 44, "ん～なんであんたと、ひと夏を\n過ごすことになったのかな…\n結構楽しいからいいけど！\nさ、まだまだ遊ぶわよ！", 107801, 0, 150, 8);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "スズメ", 2, 91002, 8, 45, "あなたと過ごすはじめての夏…\nいまからドキドキが止まりません\n楽しくて素敵な思い出が、\nまた一つ増えるんですね♪", 107701, 0, 150, 9);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40001, "タマキ", 2, 91002, 8, 46, "夏は一番の稼ぎ時にゃのに、\n今年はキミと過ごしたいって\n思ってるにゃ楽しい思い出\n増やしてくれるかにゃ？", 107901, 0, 150, 10);
