INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40011, "リリ", 1, 24001, 2, 321, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 125801, 0, 1, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40011, "クリア", 1, 24001, 2, 322, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 126001, 0, 1, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40011, "プレシア", 1, 24001, 2, 323, "んーと。\nこれ、あげる。\nはい", 126101, 0, 1, 3);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40011, "リリ", 2, 24001, 2, 324, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 125801, 0, 1, 4);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40011, "クリア", 2, 24001, 2, 325, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 126001, 0, 1, 5);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (40011, "プレシア", 2, 24001, 2, 326, "お兄。\nきてくれて、うれしい", 126101, 0, 1, 6);
